package com.portfolio.fraud.service;
import com.portfolio.fraud.dto.TransactionDtos.*; import com.portfolio.fraud.entity.*; import com.portfolio.fraud.repository.AccountRepository; import java.util.UUID; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AccountService { private final LedgerJournal journal; private final AccountRepository accounts; public AccountService(AccountRepository a,LedgerJournal j){accounts=a;journal=j;} @Transactional public AccountResponse create(User user,CreateAccountRequest request){Account account=accounts.save(new Account(nextNumber(),user,request.accountType(),request.initialBalance(),request.currency()));journal.baseline(account);return map(account);} private String nextNumber(){return "LG"+UUID.randomUUID().toString().replace("-","").substring(0,24).toUpperCase();} private AccountResponse map(Account a){return new AccountResponse(a.getId(),a.getAccountNumber(),a.getAccountType(),a.getBalance(),a.getCurrency(),a.getStatus().name());}}
